// Resolve Google Drive URL para imagem
function resolveUrl(url) {
  if (!url) return null;
  const match = url.match(/drive\.google\.com\/(?:file\/d\/|open\?id=)([^/?&]+)/);
  if (match) return `https://lh3.googleusercontent.com/d/${match[1]}`;
  return url;
}

// Resolve Google Drive URL para download direto (vídeo)
function resolveVideoUrl(url) {
  if (!url) return null;
  const match = url.match(/drive\.google\.com\/(?:file\/d\/|open\?id=)([^/?&]+)/);
  if (match) return `https://drive.google.com/uc?export=download&id=${match[1]}`;
  return url;
}

// Converte data/hora de Brasília (UTC-3) para Unix timestamp UTC
function toUtcTimestamp(date, time) {
  const t = time || '09:00';
  const [y, m, d] = date.split('-').map(Number);
  const [h, min] = t.split(':').map(Number);
  return Math.floor(Date.UTC(y, m - 1, d, h + 3, min, 0) / 1000);
}

const body = $input.first().json.body;

if (!body.page_id || !body.page_token) {
  throw new Error('page_id e page_token são obrigatórios');
}

const contentType = body.content_type || 'imagem';
const isReel      = contentType === 'reel';

// media_urls: passa URLs brutas (sem resolver) para o nó publicar tratar por tipo
const mediaUrls = Array.isArray(body.media_urls)
  ? body.media_urls.filter(Boolean)
  : [];

const publishImmediately = !!body.publish_immediately;

return [{
  json: {
    content_id:          body.content_id,
    content_type:        contentType,
    caption:             body.caption || '',
    image_url:           isReel ? resolveVideoUrl(body.image_url) : resolveUrl(body.image_url),
    media_urls:          mediaUrls,
    scheduled_ts:        publishImmediately ? null : toUtcTimestamp(body.scheduled_date, body.scheduled_time),
    publish_immediately: publishImmediately,
    page_id:             body.page_id,
    page_token:          body.page_token,
    ig_account_id:       body.ig_account_id || null,
  }
}];

// ── Helpers ───────────────────────────────────────────────────────────────
function parseJson(data) {
  if (typeof data === 'string') { try { return JSON.parse(data); } catch(e) { return {}; } }
  return data || {};
}

function toFormBody(obj) {
  return Object.entries(obj)
    .filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(String(v)))
    .join('&');
}

async function postForm(url, params) {
  const resp = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: toFormBody(params),
  });
  const text = await resp.text();
  return parseJson(text);
}

// Resolve Drive URL para imagem
function resolveUrl(url) {
  if (!url) return null;
  const match = url.match(/drive\.google\.com\/(?:file\/d\/|open\?id=)([^/?&]+)/);
  if (match) return `https://lh3.googleusercontent.com/d/${match[1]}`;
  return url;
}

// Resolve Drive URL para download direto (vídeo)
function resolveVideoUrl(url) {
  if (!url) return null;
  const match = url.match(/drive\.google\.com\/(?:file\/d\/|open\?id=)([^/?&]+)/);
  if (match) return `https://drive.google.com/uc?export=download&id=${match[1]}`;
  return url;
}

// Detecta se URL é de vídeo (pela extensão)
function isVideoUrl(url) {
  if (!url) return false;
  return /\.(mp4|mov|avi|webm|m4v)/i.test(url);
}

// Cria container de mídia no Instagram e publica
async function igCreateAndPublish(igId, containerParams, publishToken, GRAPH) {
  const containerResp = await postForm(`${GRAPH}/${igId}/media`, containerParams);
  if (containerResp.error) return { post_id: null, error: containerResp.error.message };
  if (!containerResp.id)   return { post_id: null, error: 'Instagram não retornou creation_id' };

  const publishResp = await postForm(`${GRAPH}/${igId}/media_publish`, {
    creation_id:  containerResp.id,
    access_token: publishToken,
  });
  return {
    post_id: publishResp.id || containerResp.id,
    error:   publishResp.error?.message || null,
  };
}

// ── Contexto ───────────────────────────────────────────────────────────────
const prep        = $('Preparar Dados').first().json;
const tokenResp   = $input.first().json;
const GRAPH       = 'https://graph.facebook.com/v21.0';
const pageToken   = tokenResp.access_token || prep.page_token;
const now         = Math.floor(Date.now() / 1000);
const type        = prep.content_type;
const isStory     = type === 'story';
const immediately = !!prep.publish_immediately;

// Validação de tempo (apenas para agendamentos futuros, exceto story)
if (!immediately && !isStory && prep.scheduled_ts < now + 600) {
  const msg = 'Data de agendamento deve ser pelo menos 10 minutos no futuro';
  return [{ json: { content_id: prep.content_id, update: {},
    facebook: { post_id: null, error: msg }, instagram: { post_id: null, error: msg } }}];
}

// ── FACEBOOK ───────────────────────────────────────────────────────────────
let fbPostId = null, fbError = null;
try {
  if (isStory) {
    // Story: publica cada frame como story separado (imagem ou vídeo)
    const storyUrls = (prep.media_urls && prep.media_urls.length > 0)
      ? prep.media_urls
      : (prep.image_url ? [prep.image_url] : []);
    for (const rawUrl of storyUrls) {
      const isVid    = isVideoUrl(rawUrl);
      const frameUrl = isVid ? resolveVideoUrl(rawUrl) : resolveUrl(rawUrl);
      const endpoint = `${GRAPH}/${prep.page_id}/${isVid ? 'video_stories' : 'photo_stories'}`;
      const storyParams = isVid
        ? { file_url: frameUrl, access_token: pageToken }
        : { url: frameUrl, access_token: pageToken };
      const r = await postForm(endpoint, storyParams);
      if (r.post_id || r.id) fbPostId = r.post_id || r.id;
      if (r.error && !fbPostId) fbError = r.error.message || null;
    }

  } else if (type === 'reel' && prep.image_url) {
    // Reel Facebook: URL de download do Drive (já resolvida em Preparar Dados)
    const p = {
      file_url:     prep.image_url,
      published:    immediately ? 'true' : 'false',
      access_token: pageToken,
      ...(prep.caption ? { description: prep.caption } : {}),
      ...(!immediately ? { scheduled_publish_time: String(prep.scheduled_ts) } : {}),
    };
    const r = await postForm(`${GRAPH}/${prep.page_id}/videos`, p);
    fbPostId = r.id || null;
    fbError  = r.error?.message || null;

  } else if (type === 'carrossel' && prep.media_urls?.length >= 2) {
    // Carrossel Facebook: multi-photo post com attached_media
    const photoIds = [];
    for (const rawUrl of prep.media_urls) {
      const r = await postForm(`${GRAPH}/${prep.page_id}/photos`, {
        url:          resolveUrl(rawUrl),
        published:    'false',
        access_token: pageToken,
      });
      if (r.id) photoIds.push({ media_fbid: r.id });
    }
    if (photoIds.length >= 1) {
      const r = await postForm(`${GRAPH}/${prep.page_id}/feed`, {
        message:        prep.caption || '',
        attached_media: JSON.stringify(photoIds),
        published:      immediately ? 'true' : 'false',
        access_token:   pageToken,
        ...(!immediately ? { scheduled_publish_time: String(prep.scheduled_ts) } : {}),
      });
      fbPostId = r.id || null;
      fbError  = r.error?.message || null;
    }

  } else {
    // Imagem simples
    const imgUrl   = prep.image_url;
    const endpoint = imgUrl
      ? `${GRAPH}/${prep.page_id}/photos`
      : `${GRAPH}/${prep.page_id}/feed`;
    const p = {
      published:    immediately ? 'true' : 'false',
      access_token: pageToken,
      ...(!immediately ? { scheduled_publish_time: String(prep.scheduled_ts) } : {}),
      ...(imgUrl ? { url: imgUrl, caption: prep.caption } : { message: prep.caption }),
    };
    const r = await postForm(endpoint, p);
    fbPostId = r.id || null;
    fbError  = r.error?.message || null;
  }
} catch(e) {
  fbError = String(e.message);
}

// ── INSTAGRAM ──────────────────────────────────────────────────────────────
let igPostId = null, igError = null;

if (prep.ig_account_id) {
  try {
    if (type === 'carrossel' && prep.media_urls?.length >= 2) {
      // Carrossel Instagram
      const itemIds = [];
      for (const rawUrl of prep.media_urls) {
        const r = await postForm(`${GRAPH}/${prep.ig_account_id}/media`, {
          image_url:        resolveUrl(rawUrl),
          is_carousel_item: 'true',
          access_token:     pageToken,
        });
        if (r.error) { igError = r.error.message; break; }
        if (r.id)    itemIds.push(r.id);
      }
      if (!igError && itemIds.length >= 2) {
        const carouselParams = {
          media_type:   'CAROUSEL',
          children:     itemIds.join(','),
          caption:      prep.caption,
          access_token: pageToken,
          ...(!immediately ? { published: 'false', scheduled_publish_time: String(prep.scheduled_ts) } : {}),
        };
        const result = await igCreateAndPublish(prep.ig_account_id, carouselParams, pageToken, GRAPH);
        igPostId = result.post_id;
        igError  = result.error;
      }

    } else if (type === 'reel' && prep.image_url) {
      // Reel Instagram: URL de download do Drive (já resolvida em Preparar Dados)
      const p = {
        media_type:   'REELS',
        video_url:    prep.image_url,
        caption:      prep.caption,
        access_token: pageToken,
        ...(!immediately ? { published: 'false', scheduled_publish_time: String(prep.scheduled_ts) } : {}),
      };
      const result = await igCreateAndPublish(prep.ig_account_id, p, pageToken, GRAPH);
      igPostId = result.post_id;
      igError  = result.error;

    } else if (isStory) {
      // Story Instagram: publica cada frame como story separado (imagem ou vídeo)
      const storyUrls = (prep.media_urls && prep.media_urls.length > 0)
        ? prep.media_urls
        : (prep.image_url ? [prep.image_url] : []);
      for (const rawUrl of storyUrls) {
        const isVid    = isVideoUrl(rawUrl);
        const frameUrl = isVid ? resolveVideoUrl(rawUrl) : resolveUrl(rawUrl);
        const igStoryParams = { media_type: 'STORIES', access_token: pageToken };
        if (isVid) { igStoryParams.video_url = frameUrl; } else { igStoryParams.image_url = frameUrl; }
        const result = await igCreateAndPublish(prep.ig_account_id, igStoryParams, pageToken, GRAPH);
        if (result.post_id) igPostId = result.post_id;
        if (result.error && !igPostId) igError = result.error;
      }

    } else if (prep.image_url) {
      // Imagem simples Instagram
      const p = {
        image_url:    prep.image_url,
        caption:      prep.caption,
        access_token: pageToken,
        ...(!immediately ? { published: 'false', scheduled_publish_time: String(prep.scheduled_ts) } : {}),
      };
      const result = await igCreateAndPublish(prep.ig_account_id, p, pageToken, GRAPH);
      igPostId = result.post_id;
      igError  = result.error;
    }
  } catch(e) {
    igError = String(e.message);
  }
}

// ── Payload para Supabase ──────────────────────────────────────────────────
const update = {};
if (fbPostId) update.facebook_post_id  = fbPostId;
if (igPostId) update.instagram_post_id = igPostId;
if (fbPostId || igPostId) update.status = 'published';

return [{ json: {
  content_id: prep.content_id,
  update,
  facebook:  { post_id: fbPostId, error: fbError },
  instagram: { post_id: igPostId, error: igError },
}}];

